import { expect, expectStatus, test } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor();
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");

  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const expiry = [
    yesterday.getFullYear(),
    String(yesterday.getMonth() + 1).padStart(2, "0"),
    String(yesterday.getDate()).padStart(2, "0"),
  ].join("-");
  const certificateText = [
    "Insurer: Harbor Mutual",
    "Policy Number: HM-EXP-0001",
    "Coverage Amount: $2,000,000",
    `Expiry Date: ${expiry}`,
  ].join("\n");
  const certificate = await expectStatus<{ id: string }>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: { name: "insurance_expired.txt", mimeType: "text/plain", buffer: Buffer.from(certificateText) },
      },
    }),
    201,
  );

  // Extraction runs in the background; wait until every document has finished.
  await expect
    .poll(
      async () => {
        const documents = await expectStatus<{ status: string }[]>(
          await member.get(`/api/vendors/${vendor.id}/documents`),
          200,
        );
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  await expectStatus(submitted, 200);
  const extraction = await factory.extraction(certificate.id, "reviewer");
  expect(extraction.status, "insurance extraction awaits review").toBe("pending_review");

  // Act
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  // Re-read the stored state: a refused approval must not change the extraction.
  expect((await factory.extraction(certificate.id, "reviewer")).status).toBe("pending_review");
});
